package dev.pathland.spring;

import dev.pathland.server.PathlandRegistry;
import dev.pathland.view.core.transport.FrameCodec;
import org.springframework.web.socket.BinaryMessage;
import org.springframework.web.socket.CloseStatus;
import org.springframework.web.socket.WebSocketMessage;
import org.springframework.web.socket.WebSocketSession;
import org.springframework.web.socket.handler.AbstractWebSocketHandler;

import java.net.URI;
import java.nio.ByteBuffer;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The live-updates WebSocket endpoint for one mounted app, registered at its framework
 * base ({@code /_pathland/ws} for the root mount, {@code /<path>/_pathland/ws} otherwise).
 * Sessions are 1:1 per connection: each connection is given a fresh {@code uiId} (its UI
 * model — two windows of the same browser never share a session), while the client's
 * per-window id ({@code ?wid=…} on the WS URL, kept in {@code sessionStorage}) is the
 * persisted-state scope. The ids are resolved <strong>once per connection</strong> and
 * memoized, so every message (events, close) routes to the same session. The actual session
 * logic lives in the framework-agnostic {@link PathlandRegistry}.
 */
public class PathlandSocket extends AbstractWebSocketHandler {

    private final PathlandRegistry registry;
    private final String path;
    private final Map<WebSocketSession, ConnectionIds> ids = new ConcurrentHashMap<>();
    private final Map<WebSocketSession, SpringConnection> connections = new ConcurrentHashMap<>();

    public PathlandSocket(PathlandRegistry registry) {
        this.registry = registry;
        this.path = registry.base() + "/ws";
    }

    /** The concrete endpoint path this socket is registered at. */
    public String path() {
        return path;
    }

    @Override
    public void afterConnectionEstablished(WebSocketSession session) {
        ConnectionIds connectionIds = resolveIds(session);
        ids.put(session, connectionIds);
        SpringConnection conn = new SpringConnection(session);
        connections.put(session, conn);
        registry.open(connectionIds.uiId(), connectionIds.windowId(), conn);
    }

    @Override
    public void handleMessage(WebSocketSession session, WebSocketMessage<?> message) {
        if (message instanceof BinaryMessage binary) {
            byte[] bytes = toByteArray(binary.getPayload());
            if (FrameCodec.isResync(bytes)) {
                registry.resync(uiId(session));
            } else if (FrameCodec.isPing(bytes)) {
                // A transport-liveness heartbeat probe (guest → host): reply PONG at the
                // transport layer — no actor/session dependency (spec/OPCODE.md §Transport
                // heartbeat). Best-effort: a send on a concurrently-closing session must
                // not throw out of handleMessage (Spring would close the connection).
                SpringConnection conn = connections.get(session);
                if (conn != null) {
                    try {
                        conn.send(FrameCodec.encodePong());
                    } catch (RuntimeException ignored) {
                        // the client is gone — the session's own send path will drop it
                    }
                }
            } else if (FrameCodec.isEnvironment(bytes)) {
                // The DOM client's FIRST message: seeds the session (created lazily) from
                // the ROUTE field; later messages enrich the environment (viewport, …).
                registry.environment(uiId(session), FrameCodec.decodeEnvironment(bytes));
            } else {
                registry.dispatch(uiId(session), bytes);
            }
        }
    }

    @Override
    public void afterConnectionClosed(WebSocketSession session, CloseStatus status) {
        close(session);
    }

    @Override
    public void handleTransportError(WebSocketSession session, Throwable exception) {
        close(session);
    }

    private void close(WebSocketSession session) {
        connections.remove(session);
        ConnectionIds connectionIds = ids.remove(session);
        if (connectionIds != null) {
            registry.close(connectionIds.uiId());
        }
    }

    /** The memoized UI-model id for the connection (falling back to a fresh resolve). */
    private String uiId(WebSocketSession session) {
        ConnectionIds connectionIds = ids.get(session);
        if (connectionIds == null) {
            connectionIds = resolveIds(session);
            ids.put(session, connectionIds);
        }
        return connectionIds.uiId();
    }

    /** Resolve the per-connection identity: a fresh {@code uiId} + the client's {@code wid}. */
    private ConnectionIds resolveIds(WebSocketSession session) {
        String uiId = UUID.randomUUID().toString();
        String wid = queryParam(session.getUri(), "wid");
        return new ConnectionIds(uiId, wid == null || wid.isBlank() ? UUID.randomUUID().toString() : wid);
    }

    /** Read a query parameter from the handshake URI (the client's per-window id), else null. */
    private static String queryParam(URI uri, String name) {
        if (uri == null || uri.getQuery() == null) {
            return null;
        }
        for (String pair : uri.getQuery().split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2 && name.equals(kv[0])) {
                return kv[1];
            }
        }
        return null;
    }

    /** Copy a {@link ByteBuffer} into a {@code byte[]} regardless of backing array. */
    private static byte[] toByteArray(ByteBuffer buffer) {
        ByteBuffer duplicate = buffer.duplicate();
        byte[] bytes = new byte[duplicate.remaining()];
        duplicate.get(bytes);
        return bytes;
    }

    /** The per-connection identity: UI model id + window (state-scope) id. */
    private record ConnectionIds(String uiId, String windowId) {
    }
}

package dev.pathland.quarkus;

import dev.pathland.server.PathlandHost;
import dev.pathland.server.PathlandRegistry;
import dev.pathland.view.core.transport.FrameCodec;
import io.quarkus.arc.Arc;
import io.quarkus.arc.ClientProxy;
import io.quarkus.websockets.next.OnBinaryMessage;
import io.quarkus.websockets.next.OnClose;
import io.quarkus.websockets.next.OnOpen;
import io.quarkus.websockets.next.WebSocket;
import io.quarkus.websockets.next.WebSocketConnection;
import jakarta.inject.Inject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The root app's live-updates WebSocket endpoint at {@code /_pathland/ws} (the framework
 * base of the app mounted at {@code "/"}). Sessions are 1:1 per connection: each
 * connection gets a fresh {@code uiId} (its UI model — two windows of the same browser
 * never share a session), while the client's per-window id ({@code ?wid=…} on the WS URL,
 * kept in {@code sessionStorage}) is the persisted-state scope. The session logic lives
 * in the framework-agnostic {@link PathlandRegistry}.
 *
 * <p>quarkus-websockets-next endpoints default to {@code @Singleton} — ONE shared
 * instance for all connections — so this endpoint is **stateless**: the per-connection
 * ids come from the current connection ({@code connection.id()} + the handshake), and
 * the per-connection {@link QuarkusConnection} adapters live in a map keyed by
 * connection id. A memoized {@code uiId} field would collapse every connection onto one
 * session (all browsers would share one UI model).
 *
 * <p>Mounted apps (non-root) connect at {@code /<app>/_pathland/ws} — see
 * {@link MountedPathlandSocket}.
 */
@WebSocket(path = "/_pathland/ws")
public class PathlandSocket {

    private static final Logger LOG = LoggerFactory.getLogger(PathlandSocket.class);

    @Inject
    WebSocketConnection connection;

    @Inject
    PathlandHost host;

    /** Per-connection transport adapters (the endpoint instance is shared by all connections). */
    private final ConcurrentHashMap<String, QuarkusConnection> transports = new ConcurrentHashMap<>();

    @OnOpen
    void open() {
        PathlandRegistry registry = host.registry("/");
        if (registry == null) {
            return;
        }
        // Resolve the concrete connection while the session context is active: the CDI
        // bean is session-scoped, so its client proxy would fail off-thread. ClientProxy
        // unwraps it to the real connection, whose send methods work from any thread.
        WebSocketConnection resolved =
                ClientProxy.unwrap(Arc.container().instance(WebSocketConnection.class).get());
        QuarkusConnection transport = new QuarkusConnection(resolved);
        // Key by the injected proxy's id — the SAME id onBinary/close use — so the
        // transport is always found for the current connection.
        String id = connection.id();
        transports.put(id, transport);
        registry.open(id, resolveWindowId(resolved), transport);
    }

    @OnClose
    void close() {
        String id = connection.id();
        QuarkusConnection transport = transports.remove(id);
        if (transport != null) {
            transport.close(); // stop the keep-alive scheduler + mark failed
        }
        PathlandRegistry registry = host.registry("/");
        if (registry != null) {
            registry.close(id);
        }
    }

    @OnBinaryMessage
    void onBinary(byte[] message) {
        String id = connection.id();
        PathlandRegistry registry = host.registry("/");
        if (registry == null) {
            return;
        }
        if (FrameCodec.isResync(message)) {
            registry.resync(id);
        } else if (FrameCodec.isPing(message)) {
            // A transport-liveness heartbeat probe (guest → host): reply PONG at the
            // transport layer — no actor/session dependency, and a PING never creates
            // or wakes a session (spec/OPCODE.md §Transport heartbeat).
            QuarkusConnection t = transports.get(id);
            if (t == null) {
                LOG.debug("ws ping: no transport for connection {}", id);
            } else {
                t.send(FrameCodec.encodePong());
            }
        } else if (FrameCodec.isEnvironment(message)) {
            // The DOM client's FIRST message: seeds the session (created lazily) from the
            // ROUTE field; later messages enrich the environment (viewport, …).
            registry.environment(id, FrameCodec.decodeEnvironment(message));
        } else {
            registry.dispatch(id, message);
        }
    }

    /** The {@code wid} from the handshake query string (the client's per-window id), else a fresh id. */
    private static String resolveWindowId(WebSocketConnection conn) {
        String query = conn.handshakeRequest().query();
        if (query != null) {
            for (String pair : query.split("&")) {
                String[] kv = pair.split("=", 2);
                if (kv.length == 2 && "wid".equals(kv[0]) && !kv[1].isBlank()) {
                    return kv[1];
                }
            }
        }
        return UUID.randomUUID().toString();
    }
