@ApplicationScoped
public class PathlandApp {
    private static final int MAX_EVENT_BATCH = 1 << 16;

    private final ExecutorService actor = Executors.newSingleThreadExecutor(...);
    private final Map<String, SessionApp> sessions = new ConcurrentHashMap<>();
    private final StateStore<Integer> countStore;
    private final StateStore<String> nameStore;

    @PostConstruct
    void init() {
        // create stores (probe Redis; fall back to in-memory)
    }

    public String renderHtml(String sessionId) {
        SessionApp app = new SessionApp(sessionId, countStore, nameStore);
        try {
            return app.renderHtml();
        } finally {
            app.close();
        }
    }

    public void open(String sessionId, WebSocketConnection connection) {
        actor.execute(() -> {
            SessionApp old = sessions.remove(sessionId);
            if (old != null) old.close();
            SessionApp app = new SessionApp(sessionId, countStore, nameStore);
            app.connect(connection);
            sessions.put(sessionId, app);
        });
    }

    public void dispatch(String sessionId, byte[] message) {
        if (message.length > MAX_EVENT_BATCH) return;
        actor.execute(() -> {
            SessionApp app = sessions.get(sessionId);
            if (app != null) app.dispatch(message);
        });
    }

    public void close(String sessionId) {
        actor.execute(() -> {
            SessionApp app = sessions.remove(sessionId);
            if (app != null) app.close();
        });
    }

    @PreDestroy
    void shutdown() {
        sessions.values().forEach(SessionApp::close);
        sessions.clear();
        actor.shutdown();
    }
}
```

