@WebSocket(path = "/ws")
public class PathlandSocket {
    @Inject WebSocketConnection connection;
    @Inject PathlandApp app;

    @OnOpen
    void open() {
        String sessionId = sessionIdFromCookie();
        WebSocketConnection real = ClientProxy.unwrap(Arc.container().instance(WebSocketConnection.class).get());
        app.open(sessionId, real);
    }

    @OnClose
    void close() {
        String sessionId = sessionIdFromCookie();
        app.close(sessionId);
    }

    @OnBinaryMessage
    void onBinary(byte[] message) {
        app.dispatch(sessionIdFromCookie(), message);
    }

    private String sessionIdFromCookie() {
        String cookie = connection.handshakeRequest().header("Cookie");
        if (cookie == null) return UUID.randomUUID().toString();
        for (String part : cookie.split(";")) {
            String[] kv = part.trim().split("=", 2);
            if (kv.length == 2 && kv[0].equals("session")) return kv[1];
        }
        return UUID.randomUUID().toString();
    }
}
```

