/** A safe navigational URL for an attributed-text link (`javascript:` etc. rejected). */
function safeHref(raw: string): string | null {
  const value = raw.trim();
  if (!value) {
    return null;
  }
  try {
    const url = new URL(value, document.baseURI);
    switch (url.protocol) {
      case "http:":
      case "https:":
      case "mailto:":
      case "tel:":
        return value;
      default:
        return null;
    }
  } catch {
    return null;
  }
}

/** A safe resource URL for an image/media source (`javascript:`/`data:text` rejected). */
function safeSrc(raw: string): string | null {
  const value = raw.trim();
  if (!value) {
    return "";
  }
  try {
    const url = new URL(value, document.baseURI);
    switch (url.protocol) {
      case "http:":
      case "https:":
      case "blob:":
        return value;
      case "data:":
        return /^data:(?:image|audio|video)\//i.test(value) ? value : null;
      default:
        return null;
    }
  } catch {
    return null;
  }
}

